import React, { useState, useEffect, useRef } from 'react';
import PropTypes, { shape } from 'prop-types';
import OpenSeadragon from 'openseadragon';
import { AnnotationToolkit, RectangleTool } from 'osd-paperjs-annotation';
import { DSAAdapter } from './dsaGeoJsonAdapter';

/* OpenSeadragon and PaperJS Component that allows Dash to interact with the OpenSeadragon viewer */
const DashPaperdragon = (props) => {
  const { id, // id of the div element created for this viewer
    config = {}, // configuration options for the component with default empty object
    tileSources, // the image source to view; can change depending on user input
    zoomLevel, // output property, sent by the component back to dash
    curMousePosition, // output property, sent by the component back to dash
    viewportBounds, // output property, sent by the component back to dash
    outputFromPaper, // output property, seny by the component back to dash
    inputToPaper, // input property, telling the component how to update the paper overlay
    tileSourceProps, // input property, updates tileLayers  x offset, y, rotation or opacity
    baseImageWidth, // output property, sent by the component back to dash for tiledImage[0] width
    viewerWidth = 640,  //viewer Width in pixels
    viewerHeight = 480, //viewer Height in pixels
    curShapeObject = null, // output property, sent by the component back to dash this is the last shape object that was hovered over
    pixelColor = null, // output property, sent by the component back to dash with the color data from the pixel under the cursor
    setProps,
  } = props;

  // Set up references to common variables
  const viewerRef = useRef(null);
  const tiledImageRef = useRef(null);
  const overlayRef = useRef(null);
  const toolkitRef = useRef(null);
  const paperRef = useRef(null);
  const hoveredItemRef = useRef(null);
  const mousePosRef = useRef({ x: 0, y: 0 });
  const paperMousePosRef = useRef({ x: 0, y: 0 });
  const keyDownRef = useRef(null);
  const creatingRef = useRef(null);
  const editingRef = useRef(null);
  const viewerIsOpening = useRef(null);

  // Default configuration with fallbacks
  const defaultConfig = {
    eventBindings: [],
    callbacks: [],
    properties: {},
    defaultStyle: {
      fillColor: "red",
      strokeColor: "red",
      rescale: {
        strokeWidth: 1,
      },
      fillOpacity: 0.2,
    },
    styles: {},
  };

  // Merge provided config with defaults
  const mergedConfig = {
    ...defaultConfig,
    ...config,
    eventBindings: [...(config.eventBindings || [])],
    callbacks: [...(config.callbacks || [])],
    properties: { ...(config.properties || {}) },
    defaultStyle: { ...defaultConfig.defaultStyle, ...(config.defaultStyle || {}) },
    styles: { ...(config.styles || {}) },
  };

  /** Define actions */
  const actionsRef = useRef({
    drawItems,
    clearItems,
    drawDsaAnnotations,
    drawGeoJsonFeatureSet,
    cycleProp,
    cyclePropReverse,
    deleteItem,
    dashCallback,
    newItem,
    getColor,
    zoomToBounds,
    addTileSource,
    removeTileSource,
    grabColor,
    editItem,
  });

  function raiseEvent(eventName, data) {
    executeCallbacks(eventName, data);
  }

  /** Create viewer within a useEffect */
  useEffect(() => {
    if (!viewerRef.current) {
      createViewer();
    }
    // Clean up the viewer when the component unmounts
    return () => {
      if (viewerRef.current) {

        // if (tiledImageRef.paperLayer) tiledImageRef.paperLayout.remove();

        viewerRef.current.destroy();
        viewerRef.current = null;
        tiledImageRef.current = null;

      }
    };
  }, []);


  useEffect(() => {
    const viewer = viewerRef.current;
    if (!viewer || !tileSourceProps) {
      console.debug('No viewer or tileSourceProps available');
      return;
    }

    try {
      console.debug('Updating tile source properties:', tileSourceProps);

      for (let i = 0; i < tileSourceProps.length; i++) {
        const props = tileSourceProps[i];
        const curTileSource = viewer.world.getItemAt(props.index !== undefined ? props.index : i);

        if (!curTileSource) {
          console.warn(`No tile source found at index ${i}`);
          continue;
        }

        if (!props) {
          console.warn(`Invalid properties for tile source ${i}`);
          continue;
        }

        console.debug(`Updating tile source ${i} with properties:`, props);

        // Handle visibility and opacity together
        if (props.visible !== undefined || props.opacity !== undefined) {
          const isVisible = props.visible !== undefined ? props.visible : curTileSource.getVisible();
          const opacity = props.opacity !== undefined ? props.opacity : curTileSource.getOpacity();
          curTileSource.setOpacity(isVisible ? opacity : 0);
        }

        // Update position if either x or y is provided
        if (props.x !== undefined || props.y !== undefined) {
          const currentPos = curTileSource.getBounds().getTopLeft();
          curTileSource.setPosition({
            x: props.x !== undefined ? props.x : currentPos.x,
            y: props.y !== undefined ? props.y : currentPos.y
          });
        }

        // Update rotation if provided
        if (props.rotation !== undefined) {
          curTileSource.setRotation(props.rotation);
        }

        // Only update width/height if explicitly changed
        // This prevents unintended viewport changes
        if (props.width !== undefined && props.width !== curTileSource.getWidth()) {
          curTileSource.setWidth(props.width);
        }
        if (props.height !== undefined && props.height !== curTileSource.getHeight()) {
          curTileSource.setHeight(props.height);
        }

        // Update composite operation if specified
        if (props.compositeOperation !== undefined) {
          curTileSource.setCompositeOperation(props.compositeOperation);
        }

        // Force a redraw of just this tile
        curTileSource.draw();
      }

    } catch (error) {
      console.error('Error updating tile source properties:', error);
    }
  }, [tileSourceProps]);


  /** Open an image based on imageSrc property */
  useEffect(() => {
    if (viewerRef.current && tileSources) {
      // Update the image source
      viewerIsOpening.current = true;
      viewerRef.current.addOnceHandler('open', () => {
        const cachedInputToPaper = inputToPaper;
        viewerIsOpening.current = false;
        handleInputToPaper(cachedInputToPaper);
      });

      viewerRef.current.open(tileSources);
    }
  }, [tileSources, inputToPaper]);

  /* respond to changes in the inputToPaper property */
  useEffect(handleInputToPaper, [inputToPaper]);
  function handleInputToPaper() {
    // if the tiledImage or inputToPaper are null, nothing to do, just return
    if (!inputToPaper || !tiledImageRef.current) {
      return;
    }

    for (const action of inputToPaper.actions) {
      let func = actionsRef.current[action.type];
      if (!func) {
        alert('No action defined for type ' + action.type);
      } else {
        // console.log('Action:', action);
        func(action);
      }
    }



    // clear the inputToPaper property so we can listen for more changes
    setProps(inputToPaper, null);
  }

  // Functions that can be accessed by Dash via actions and/or bindings
  function clearItems() {
    tiledImageRef.current.paperLayer.clear();
  }


  function drawGeoJsonFeatureSet(action) {
    const list = action.itemList || [];
    if (!list.length) {
      console.warn('No items were provided in the itemList property');
    }
    // Function is empty beyond this point
  }

  function drawDsaAnnotations(action) {
    console.log("drawDsaAnnotations called with action:", action);
    const list = action.itemList || [];
    if (!list.length) {
      console.warn('No items were provided in the itemList property');
      return;
    }

    // Clear existing annotations first
    clearItems();

    // Process each annotation
    for (const annotation of list) {
      try {
        console.log("Processing annotation:", annotation);
        // Convert DSA annotation to GeoJSON
        const geoJson = DSAAdapter.dsaToGeoJson(annotation);
        console.log("Converted to GeoJSON:", geoJson);

        // Add the features to the viewer using drawItems
        drawItems({ itemList: geoJson });
      } catch (error) {
        console.error('Error processing annotation:', error);
      }
    }
  }



  function drawItems(action) {
    const list = action.itemList || [];
    if (!list.length) {
      console.warn('No items were provided in the itemList property');
    }
    for (const i of list) {
      const item = makeItem(i);
      // Update fill opacity if specified
      if (i.args && i.args[0] && i.args[0].fillOpacity !== undefined) {
        item.fillColor.alpha = i.args[0].fillOpacity;
      }
      tiledImageRef.current.addPaperItem(item);
    }
  }

  function deleteItem(opts) {

    raiseEvent('item-deleted', { item: opts.item });
    // console.log(opts)
    if (opts.item) {
      opts.item.remove();
    } else if (opts.id) {
      console.log(`deleteItem with id ${opts.id}`);
      tiledImageRef.current.paperItems.filter(i => i.data.userdata.objectId == opts.id).forEach(item => item.remove());
    } else {
      console.error('deleteItem  called without item or id field');
    }

  }

  function newItem(opts) {
    if (creatingRef.current) {
      const item = creatingRef.current;

      paperRef.current.rectangleTool.deactivate(true);
      if (item.isPlaceholder) {
        item.remove();
        console.log('Rectangle aborted');
      } else {
        item.selected = false;
        console.log('Item created', item);
        const bounds = item.bounds;
        raiseEvent('item-created', {
          point: { x: bounds.x, y: bounds.y },
          size: { width: bounds.width, height: bounds.height }
        })
        creatingRef.current = null;
      }

    } else {
      console.log('newItem called', opts, paperRef.current.rectangleTool);
      let placeholder = toolkitRef.current.makePlaceholderItem(mergedConfig.defaultStyle);

      let item = placeholder.paperItem;

      if (mergedConfig.defaultStyle.fillOpacity !== undefined) {
        item.fillColor.alpha = mergedConfig.defaultStyle.fillOpacity;
      }

      item.selected = true;
      item.isPlaceholder = true;
      tiledImageRef.current.addPaperItem(item);
      creatingRef.current = item;
      item.on('item-replaced', (ev) => creatingRef.current = ev.item);
      paperRef.current.rectangleTool.activate();
    }
  }

  function cycleProp(opts, bound, reverse) {
    let item = opts.item;
    let prop = bound.property;
    if (!item || !prop) {
      console.error('There was a problem with the item or property');
      return;
    }

    // look up the array of options for this property from the config object
    let propArray = mergedConfig.properties[prop];
    if (!propArray || !Array.isArray(propArray)) {
      console.error(`config.${prop} is ${typeof propArray}; it must be an Array to use cycleProp`);
      return;
    }

    // figure out what the new value for this property is, and set it on the item.data object
    let currentVal = item.data.userdata[prop];
    let newIndex = (propArray.indexOf(currentVal) + (reverse ? propArray.length - 1 : 1)) % propArray.length;
    let newVal = propArray[newIndex];
    item.data.userdata[prop] = newVal;

    // look up a style that goes with this property key:value pair
    let style = mergedConfig.styles && mergedConfig.styles[prop] && mergedConfig.styles[prop][newVal];
    if (style) {
      item.set(style);
    }

    // refresh the fill opacity and rescalable properties
    if (item.fillColor) {
      item.fillColor.alpha = item.fillOpacity;
    }

    // Add safety check for applyRescale
    if (item && typeof item.applyRescale === 'function') {
      item.applyRescale();
    } else {
      // If applyRescale is not available, set default rescale properties
      if (item) {
        item.rescale = item.rescale || {};
        item.rescale.strokeWidth = item.rescale.strokeWidth || 1;
        // Add any other default rescale properties here if needed
      }
    }

    raiseEvent('property-changed', { item: item.data.userdata, property: prop });
  }

  function cyclePropReverse(opts, bound) {
    cycleProp(opts, bound, true);
  }

  function dashCallback(action, data) {
    console.log('dashCallback', action, data);
    setProps({ outputFromPaper: { callback: action.callback, data: data } });
  }

  function getColor(opts) {
    const mousePos = mousePosRef.current;
    const tiledImage = tiledImageRef.current;
    if (!tiledImage) return;

    // Convert image coordinates to viewport coordinates
    const viewportPoint = tiledImage.imageToViewportCoordinates(mousePos.x, mousePos.y);

    // Convert viewport to viewer element coordinates
    const viewerCoords = tiledImage.viewer.viewport.viewportToViewerElementCoordinates(viewportPoint);

    // Get the context and device pixel ratio
    const context = tiledImage.viewer.drawer.canvas.getContext('2d');
    const r = window.devicePixelRatio || 1;

    // Round the coordinates and scale by device pixel ratio
    const x = Math.round(viewerCoords.x * r);
    const y = Math.round(viewerCoords.y * r);

    // Check if coordinates are within bounds
    const canvas = tiledImage.viewer.drawer.canvas;
    if (x < 0 || y < 0 || x >= canvas.width || y >= canvas.height) {
      return;
    }

    try {
      // Get the pixel data
      const imageData = context.getImageData(x, y, 1, 1).data;
      const pixelColor = {
        r: imageData[0],
        g: imageData[1],
        b: imageData[2]
      };
      setProps({
        pixelColor: pixelColor
      });

      // Raise an event for other callbacks
      raiseEvent('color-grabbed', {
        color: pixelColor,
        position: mousePos
      });
    } catch (error) {
      console.error('Error getting pixel color:', error);
    }
  }

  function grabColor(opts) {
    // Get the current mouse position from the ref
    const mousePos = mousePosRef.current;

    // Get the current tiledImage
    const tiledImage = tiledImageRef.current;
    if (!tiledImage) return;

    // Get the context from the canvas
    const context = tiledImage.viewer.drawer.canvas.getContext('2d');
    const r = window.devicePixelRatio;

    /* need to convert mousePos to image coordinates */
    const imageCoords = tiledImage.viewer.viewport.imageToViewerElementCoordinates(mousePos);

    // Get the pixel data at the current mouse position
    const imageData = context.getImageData(imageCoords.x * r, imageCoords.y * r, 1, 1).data;

    // Convert to RGB object
    const pixelColor = {
      r: imageData[0],
      g: imageData[1],
      b: imageData[2]
    };

    // Update the pixelColor prop
    setProps({ pixelColor });

    // Optionally raise an event for other callbacks
    raiseEvent('color-grabbed', { color: pixelColor, position: mousePos });
  }

  function createViewer() {

    // if viewer exists, return immediately
    if (viewerRef.current) {
      return;
    }

    // Create a new viewer
    const viewer = viewerRef.current = OpenSeadragon({
      id: id,
      prefixUrl: '//openseadragon.github.io/openseadragon/images/', // Update with your image path
      crossOriginPolicy: 'Anonymous',
      ajaxWithCredentials: false,
      loadTilesWithAjax: true,
      imageLoaderLimit: 5,
      timeout: 90000,
      /* TO DO: add additional properties like navigator */
    });

    viewer.addHandler('close', () => tiledImageRef.current = null);
    viewer.world.addHandler('add-item', ev => tiledImageRef.current = ev.item);

    // suppress default OSD keydown handling for a subset of keys
    viewer.addHandler('canvas-key', event => {
      if (['q', 'w', 'e', 'r', 'a', 's', 'd', 'f'].includes(event.originalEvent.key)) {
        event.preventDefaultAction = true;
      }
    });
    // add mouse tracker and other handlers
    setupInfoHandler(viewer);
    setupPaper();

    // for easier debugging: attach objects to window
    window.viewer = viewer;
  }

  function setupPaper() {
    const tk = new AnnotationToolkit(viewerRef.current, { overlay: null, addUI: false });
    console.log('Toolkit:', tk);
    toolkitRef.current = tk;

    // Comment out automatic annotation loading
    /*
    // bind to viewer.world.addItem and load any dsa annotations
    viewerRef.current.world.addHandler('add-item', async event => {
      const src = event.item.source.tilesUrl || await event.item.source.getTileUrl(0, 0, 0);
      console.log('Opened', src, event);
      if (typeof src === 'string') {
        const match = src.match(/(.*api\/+v1)\/+item\/+(.*?)\//i);
        if (match) {
          const base = match[1];
          const itemId = match[2];
          fetch(`${base}/annotation/item/${itemId}`).then(d => d.json()).then(d => {
            console.log(`Got annotations for ${itemId}:`, d);
            for (const annotation of d) {
              tk.addFeatureCollections(DSAAdapter.dsaToGeoJson(annotation), false, event.item);
            }
          })
        }
      }
    })
    */

    const overlay = overlayRef.current = tk.overlay;
    // for easier debugging: attach objects to window
    window.overlay = overlay;
    // grab a reference to paper object
    paperRef.current = overlay.paperScope;

    paperRef.current.rectangleTool = new RectangleTool(overlay.paperScope);

    // add key handlers to the paper view. TODO: this could be handled by mousetracker too I suppose 
    const view = paperRef.current.view;
    view.onKeyUp = ev => {
      keyDownRef.current = false;
      let hitResult = paperRef.current.project.hitTest(paperMousePosRef.current);
      let item = hitResult && hitResult.item;

      executeBoundEvents({ event: 'keyUp', key: ev.key, meta: ev.meta },
        { mousePosition: mousePosRef.current, item: item });
    }
    view.onKeyDown = ev => {
      if (keyDownRef.current) {
        return;
      }
      keyDownRef.current = ev.key;
      let hitResult = paperRef.current.project.hitTest(paperMousePosRef.current);
      let item = hitResult && hitResult.item;

      executeBoundEvents({ event: 'keyDown', key: ev.key, meta: ev.meta },
        { mousePosition: mousePosRef.current, item: item });
    }

    view.onMouseMove = ev => {
      paperMousePosRef.current = ev.point;
    }

  }


  /* Set up the mouse handler functions */
  function setupInfoHandler(viewer) {

    // TO DO: Add or deal with resize handler 
    // let events = ['pan', 'zoom', 'rotate', 'resize'];

    // TODO: add mouse click handler logic, coordinating with paper overlay

    viewer.addHandler('zoom', function (event) {
      const zoomValue = event.zoom;
      setProps({ zoomLevel: zoomValue });
    });

    function onViewportChange(event) {
      let tiledImage = viewer.world.getItemAt(0);
      if (tiledImage) {
        let rect = tiledImage.viewportToImageRectangle(viewer.viewport.getBounds())
        setProps({ viewportBounds: rect });
      }

    }
    viewer.addHandler('viewport-change', onViewportChange);
    viewer.addHandler('open', onViewportChange);


    let moveHandler = function (event) {
      let tiledImage = viewer.world.getItemAt(0);
      if (tiledImage) {
        let imageCoords = tiledImage.viewerElementToImageCoordinates(event.position);
        mousePosRef.current = imageCoords;
        setProps({ curMousePosition: imageCoords });
      }

    }

    let leaveHandler = function () {
      setProps({ curMousePosition: { x: null, y: null } });
    }

    // create a mousetracker for the viewer, and hook up the handlers
    new OpenSeadragon.MouseTracker({ element: viewer.element, moveHandler: moveHandler, leaveHandler: leaveHandler });

  }


  function badAction(a) {
    alert('Bad action, see console');
    console.warn('Bad action:', a);
  }


  function makeItem(definition) {
    // TODO: make this fully configurable from the dash side via config
    if (!definition.paperType) {
      console.error('makeItem requires the object type in the paper field (e.g. paper: Path.Rectangle)');
      return;
    }
    let constructor = paperRef.current;
    for (const part of definition.paperType.split('.')) {
      constructor = constructor[part];
      if (!constructor) {
        console.error(`Bad paper constructor: paper.${definition.paper} does not exist`);
      }
    }

    if (!Array.isArray(definition.args)) {
      definition.args = [definition.args];
    }
    if (!definition.userdata instanceof Object) {
      definition.userdata = {
        userdata: definition.userdata
      };
    }

    // Map DSA properties to Paper.js properties
    if (definition.args[0]) {
      const args = definition.args[0];
      // Map fillColor from DSA format
      if (args.fillColor === undefined && args.properties?.fillColor !== undefined) {
        args.fillColor = args.properties.fillColor;
      }
      // Map strokeColor from DSA format (lineColor)
      if (args.strokeColor === undefined && args.properties?.lineColor !== undefined) {
        args.strokeColor = args.properties.lineColor;
      }
      // Map strokeWidth from DSA format (lineWidth)
      if (args.strokeWidth === undefined && args.properties?.lineWidth !== undefined) {
        args.strokeWidth = args.properties.lineWidth;
      }
      // Map fillOpacity from DSA format
      if (args.fillOpacity === undefined) {
        // Extract opacity from rgba fillColor if present
        const fillColorMatch = (args.fillColor || args.properties?.fillColor || '').match(/rgba\(.*,\s*([\d.]+)\)/);
        args.fillOpacity = fillColorMatch ? parseFloat(fillColorMatch[1]) : 0.2;
      }
    }

    let item = new constructor(...definition.args);
    if (item.fillColor) {
      item.fillColor.alpha = item.fillOpacity;
    }

    // Initialize rescale property with defaults if not present
    if (!item.rescale) {
      item.rescale = {
        strokeWidth: definition.args[0]?.rescale?.strokeWidth ||
          definition.args[0]?.properties?.lineWidth ||
          1
      };
    }

    // bind some extra properties to keep track of where in the array we are, and the original definition of the object
    Object.assign(item.data, definition);

    // add mouseEnter and mouseLeave handlers
    item.onMouseEnter = event => {
      setProps({ "curShapeObject": event.target.data });
      hoveredItemRef.current = event.target.data;
      executeBoundEvents({ event: 'mouseEnter' }, { item: event.target.data });
    }
    item.onMouseLeave = event => {
      setProps({ "curShapeObject": null });
      hoveredItemRef.current = null;
      executeBoundEvents({ event: 'mouseLeave' }, { item: event.target.data });
    }

    // register the item with the annotation toolkit
    AnnotationToolkit.registerFeature(item);

    return item;
  }

  function executeCallbacks(eventName, data) {
    if (mergedConfig.callbacks) {
      let callbacks = mergedConfig.callbacks.filter(a => a.eventName == eventName).map(a => a.callback);
      for (const cb of callbacks) {
        dashCallback({ callback: cb }, data);
      }
    }
  }

  function executeBoundEvents(filters, opts) {
    if (mergedConfig.eventBindings) {
      let enterActions = mergedConfig.eventBindings.filter(a => match(a, filters));
      for (const a of enterActions) {
        const func = actionsRef.current[a.action];
        if (func) {
          func(opts, a);
        } else {
          badAction(a);
        }
      }
    }
  }

  function match(obj, filters) {
    for (const [key, value] of Object.entries(obj)) {
      if (key in filters && filters[key] !== value) {
        return false
      }
    }
    return true;
  }

  // Add the zoomToBounds function
  function zoomToBounds(action) {
    const viewer = viewerRef.current;
    if (!viewer) return;

    const bounds = action.bounds;
    if (!bounds) {
      console.warn('No bounds provided for zoomToBounds action');
      return;
    }

    // Convert image coordinates to viewport coordinates
    const tiledImage = viewer.world.getItemAt(0);
    if (!tiledImage) return;

    // Convert the bounds to viewport coordinates
    const viewportBounds = new OpenSeadragon.Rect(
      bounds.x,
      bounds.y,
      bounds.width,
      bounds.height
    );
    const viewportRect = tiledImage.imageToViewportRectangle(viewportBounds);

    // Add a bit of padding (10%) and fit bounds
    viewer.viewport.fitBounds(viewportRect, true);
  }

  /** Add a new tile source to the viewer */
  function addTileSource(action) {
    if (!viewerRef.current) return;

    const source = action.source;
    const options = {
      tileSource: source,
      x: source.x || 0,
      y: source.y || 0,
      opacity: source.opacity || 1,
      rotation: source.rotation || 0,
      crossOriginPolicy: 'Anonymous',
      ajaxWithCredentials: false,
      loadTilesWithAjax: false
    };

    viewerRef.current.addTiledImage(options);
  }

  /** Remove a tile source from the viewer */
  function removeTileSource(action) {
    if (!viewerRef.current) return;

    const sourceId = action.sourceId;
    const tiledImage = viewerRef.current.world.getItemAt(sourceId);
    if (tiledImage) {
      viewerRef.current.world.removeItem(tiledImage);
    }
  }

  function editItem(opts) {
    if (creatingRef.current) {
      return; // can't edit when you're already creating an item
    }

    if (editingRef.current) {
      editingRef.current.selected = false;
      paperRef.current.rectangleTool.deactivate();
      const bounds = editingRef.current.bounds;
      const itemData = editingRef.current.annotationItem || {};
      raiseEvent('item-edited', {
        point: { x: bounds.x, y: bounds.y },
        size: { width: bounds.width, height: bounds.height },
        userdata: itemData.userdata || {},
        origRef: editingRef.current
      });
      editingRef.current = null;
    } else if (opts && opts.item) {
      editingRef.current = opts.item;
      opts.item.selected = true;
      paperRef.current.rectangleTool.activate();
    }
  }

  return (

    <div >

      <div id={id} style={{ width: viewerWidth + 'px', height: viewerHeight + 'px' }}></div>
    </div>
  );
}

DashPaperdragon.defaultProps = {};

